    let q = exact / of;
    const r = (exact % of) * 2n;
    if (r > of || (r === of && q % 2n === 1n)) q += 1n;
    return q;
  });
  let largest = 0;
  shares.forEach((h, i) => {
    if (h > shares[largest]) largest = i;
  });
  result[largest] += pot - result.reduce((sum, c) => sum + c, 0n);
